// Объявление функции через keyword function
function greet(name) {
  // name — параметр: переменная внутри функции
  console.log("Привет, " + name + "!");
}

// Вызов функции с аргументом:
greet("Анна");   // Привет, Анна!
greet("Борис");  // Привет, Борис!

// Параметры — это переменные, доступные только ВНУТРИ функции.
// Аргументы — конкретные значения, которые ты передаёшь при вызове.

// Функция с return возвращает значение
function add(a, b) {
  return a + b;  // возвращает сумму
}

// Результат можно присвоить переменной:
const result = add(5, 3);  // result = 8
console.log(result);       // 8

// Можно использовать в выражении:
console.log(add(2, 3) + 10);  // 15

// Функция БЕЗ return возвращает undefined:
function sayHi(name) {
  console.log("Привет, " + name);
  // нет return — результат undefined
}

const value = sayHi("Ann");
console.log(value);  // undefined

