// Обычная функция
function double(x) {
  return x * 2;
}

// То же через стрелочную функцию (короче):
const double = (x) => {
  return x * 2;
};

// Ещё короче — если тело одно выражение, фигурные скобки и return не нужны:
const double = (x) => x * 2;

// Если один параметр, круглые скобки тоже можно опустить:
const double = x => x * 2;

// Оба варианта возвращают то же значение:
console.log(double(5));  // 10

function greet(name = "Гость") {
  console.log("Привет, " + name + "!");
}

greet("Анна");  // Привет, Анна!
greet();        // Привет, Гость! — использовано значение по умолчанию

// Значения по умолчанию работают и для стрелочных:
const add = (a, b = 0) => a + b;
console.log(add(5));   // 5
console.log(add(5, 3)); // 8

