// Объявление через function — всплывает:
console.log(greet("Ann"));  // Привет, Ann!
function greet(name) {
  return "Привет, " + name;
}

// Стрелочная функция — НЕ всплывает:
console.log(sayHi("Ann"));  // ReferenceError!
const sayHi = (name) => "Привет, " + name;

// Всплывает только ОБЪЯВЛЕНИЕ переменной, а не ЗНАЧЕНИЕ:
// sayHi = undefined, поэтому вызов = ошибка

// this в обычной функции указывает на объект:
const user = {
  name: "Ann",
  greet() {
    return "Привет, " + this.name;  // this.name = "Ann"
  }
};
console.log(user.greet());  // Привет, Ann

// this в стрелочной функции берёт извне (undefined в strict mode):
const user2 = {
  name: "Ann",
  greet: () => {
    return "Привет, " + this.name;  // this.name = undefined!
  }
};
console.log(user2.greet());  // Привет, undefined

// Функция в переменной:
const add = (a, b) => a + b;
const func = add;  // func — тоже функция
console.log(func(2, 3));  // 5

// Передача функции как аргумент (колбэк):
function doTwice(fn) {
  fn();
  fn();
}

doTwice(() => console.log("Hello"));
// Hello
// Hello

// Возврат функции из функции:
function createMultiplier(mult) {
  return (x) => x * mult;
}

const double = createMultiplier(2);
const triple = createMultiplier(3);
console.log(double(5));  // 10
console.log(triple(5));  // 15

function sum(a, b) {
  return a + b;
}

console.log(sum(5));      // NaN — b = undefined, 5 + undefined = NaN
console.log(sum(5, 3, 1)); // 8 — третий аргумент игнорируется

// Защита: проверка на undefined
function safeSum(a, b) {
  if (a === undefined || b === undefined) {
    return 0;  // или throw new Error()
  }
  return a + b;
}

